contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz over two addresses: adminCaller (who will act as admin) and newOwner (the target owner)
    // General rule: when the admin calls setOwner(newOwner), afterwards c.owner() == newOwner.
    // The mutant that requires msg.sender == owner will violate this for some inputs where admin != owner.
    function testFuzz_property(address adminCaller, address newOwner) public {
        // keep addresses non-zero to be in wide admissible domain
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure the deployed C's admin is the test contract deployer (address(this)); so we need to
        // simulate the original deployer as adminCaller. To do that, we deploy a fresh C from adminCaller
        // by using vm.prank to impersonate adminCaller and constructing a new instance.
        // But setUp already deployed c from this contract. To respect the requirement to deploy c in setUp
        // using new C(), we instead will make adminCaller equal address(this) via fuzz wide domain by
        // assuming adminCaller == address(this) OR simulate the admin calling via address(this).
        // Simpler approach: the property concerns that the contract's admin (the deployer) can setOwner.
        // Since setUp deployed c from this test contract, address(this) is admin. We'll fuzz the actor who
        // attempts the call, and ensure we invoke the call as the admin (address(this)) so original should succeed.

        // To capture the behavioral difference, we choose cases where current owner != admin prior to call.
        // Initially, in constructor, owner == deployer (address(this)). So mutate owner away from admin first
        // by having the admin set owner to some other address (this should always succeed in reference).
        address initialAdmin = address(this);

        // pick an intermediate owner different from admin to create the scenario where admin != owner
        vm.assume(newOwner != initialAdmin);

        // Step 1: admin (this) sets owner to newOwner; original should allow this and result in owner==newOwner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: in the correct contract, when the admin (deployer) calls setOwner(newOwner),
        // the contract's owner getter equals newOwner. The mutant that requires msg.sender==owner will cause
        // this call to revert (ok==false) or leave owner unchanged when admin != owner; thus the property fails.
        assertTrue(ok && (c.owner() == newOwner));
    }
}

