pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary caller address that the fuzzer will supply.
    // General rule: only the deployer (admin) can change owner. We test that when ANY caller
    // calls setOwner, the owner stored equals the admin-set value only if that caller is admin.
    // For the reference contract this holds for all callers; the mutant will allow non-admin
    // to change owner (or prevent admin), so for some caller address the resulting owner differs.
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses canonical (not zero) but otherwise wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // admin is the address that deployed C in setUp(): address(this) at deployment time.
        // In setUp we used new C() from this contract, so the admin inside C is address(this) of the test contract.
        // We will simulate both admin and arbitrary caller trying to set owner.

        // First, record current owner (should be the deployer of C i.e., address(this) at construction time)
        address initialOwner = c.owner();

        // Try to call setOwner as the fuzzed caller and capture success without reverting the test run.
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // After the call, read owner from the contract.
        address resultingOwner = c.owner();

        // General property to assert: If the caller is NOT the admin (the test contract address at deploy time),
        // then the correct contract must NOT have changed owner (i.e., owner stays equal to initialOwner).
        // Because in the reference onlyAdmin allows only admin to change owner, any non-admin call must fail to
        // change owner. The mutant inverts the check and will allow non-admins to change owner, causing the
        // resultingOwner to differ for some fuzzed caller/newOwner inputs. We assert that for the current
        // fuzzed caller, if caller != admin then owner remains equal to initialOwner.
        address admin = address(this); // admin was this contract when deploying c

        if (caller != admin) {
            assertTrue(resultingOwner == initialOwner);
        } else {
            // If caller == admin, reference allows change: resultingOwner should equal newOwner if call succeeded.
            // We assert the known expected behavior for admin calls as well to keep the property universal.
            // Note: if admin called and the call reverted, ok==false and resultingOwner should remain initialOwner.
            if (ok) {
                assertTrue(resultingOwner == newOwner);
            } else {
                assertTrue(resultingOwner == initialOwner);
            }
        }
    }
}

