pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // deployer is msg.sender of setUp in the test VM; ensure we record it
        deployer = address(this);
        c = new C();
    }

    // Fuzzed parameter: an arbitrary address that the fuzzer will try to use as caller/actor
    function testFuzz_property(address actor) public {
        // Keep domain wide but avoid the trivial case where actor is the deployer (admin)
        // We want to check behaviour when actor may coincide with current owner but is not admin.
        vm.assume(actor != address(0));

        // initially owner == deployer (constructor set owner = msg.sender)
        address initialOwner = c.owner();
        // ensure initialOwner equals deployer
        assertTrue(initialOwner == deployer);

        // Case setup: have the admin (deployer) set owner to actor so that owner == actor and actor != admin
        // Use prank to simulate deployer calling setOwner (deployer is address(this) in setUp but in test context, use prank)
        vm.prank(deployer);
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct contract allows admin to set owner to arbitrary actor, so require that succeeded.
        // If it didn't succeed, the test can't proceed meaningfully; constrain to runs where admin can set owner.
        vm.assume(ok);

        // Now owner == actor and actor != admin (deployer). We want to assert that only admin can change owner.
        // The reference contract enforces only admin can call setOwner; thus when actor (who is current owner but not admin)
        // calls setOwner again to set owner to some other address, that call must fail (i.e., not succeed).
        // The mutant allows owner to call setOwner; thus there exist actors (when actor != admin) that will succeed and change owner.

        // Fuzz another address newOwner to attempt the change; include it as local fuzzed value by deriving from actor
        // to avoid introducing non-fuzzed parameters. We'll let the fuzzer control `actor` only; pick a deterministic newOwner
        // derived from actor so the property is universal over actor.
        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(actor, "new")))));

        // Actor (current owner but not admin) attempts to call setOwner
        vm.prank(actor);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule (single assertion): only admin can change owner, so when caller == owner != admin,
        // the call must NOT succeed; i.e., ok2 must be false. This holds for the reference and is violated by the mutant.
        assertTrue(!ok2);
    }
}

